    88  static int is_msie(h2o_req_t *req)
    89  {
    90      ssize_t cursor = h2o_find_header(&req->headers, H2O_TOKEN_USER_AGENT, -1);
    91      if (cursor == -1)
    92          return 0;
    93      if (h2o_strstr(req->headers.entries[cursor].value.base, req->headers.entries[cursor].value.len, H2O_STRLIT("; MSIE ")) ==
    94          SIZE_MAX)
    95          return 0;
    96      return 1;
    97  }
