   112  static void close_connection(struct st_h2o_http1_conn_t *conn, int close_socket)
   113  {
   114      h2o_timeout_unlink(&conn->_timeout_entry);
   115      h2o_dispose_request(&conn->req);
   116      if (conn->sock != NULL && close_socket)
   117          h2o_socket_close(conn->sock);
   118      h2o_linklist_unlink(&conn->_conns);
   119      free(conn);
   120  }
