   163  static void on_entity_read_complete(struct st_h2o_http1_conn_t *conn)
   164  {
   165      conn->_req_entity_reader = NULL;
   166      set_timeout(conn, NULL, NULL);
   167      h2o_socket_read_stop(conn->sock);
   168      process_request(conn);
   169  }
