   380  static void on_continue_sent(h2o_socket_t *sock, const char *err)
   381  {
   382      struct st_h2o_http1_conn_t *conn = sock->data;
   383
   384      if (err != NULL) {
   385          close_connection(conn, 1);
   386          return;
   387      }
   388
   389      h2o_socket_read_start(sock, reqread_on_read);
   390      conn->_req_entity_reader->handle_incoming_entity(conn);
   391  }
   392
   393  static int contains_crlf_only(const char *s, size_t len)
   394  {
   395      for (; len != 0; ++s, --len)
   396          if (!(*s == '\r' || *s == '\n'))
   397              return 0;
   398      return 1;
   399  }
   400
   401  static void send_bad_request(struct st_h2o_http1_conn_t *conn)
   402  {
   403      h2o_socket_read_stop(conn->sock);
   404      h2o_send_error_400(&conn->req, "Bad Request", "Bad Request", H2O_SEND_ERROR_HTTP1_CLOSE_CONNECTION);
   405  }
   406
   407  static void handle_incoming_request(struct st_h2o_http1_conn_t *conn)
   408  {
   409      size_t inreqlen = conn->sock->input->size < H2O_MAX_REQLEN ? conn->sock->input->size : H2O_MAX_REQLEN;
   410      int reqlen, minor_version;
   411      struct phr_header headers[H2O_MAX_HEADERS];
   412      size_t num_headers = H2O_MAX_HEADERS;
   413      ssize_t entity_body_header_index;
   414      h2o_iovec_t expect;
   415
   416      /* need to set request_begin_at here for keep-alive connection */
   417      if (conn->req.timestamps.request_begin_at.tv_sec == 0)
   418          conn->req.timestamps.request_begin_at = *h2o_get_timestamp(conn->super.ctx, NULL, NULL);
   419
   420      reqlen = phr_parse_request(conn->sock->input->bytes, inreqlen, (const char **)&conn->req.input.method.base,
   421                                 &conn->req.input.method.len, (const char **)&conn->req.input.path.base, &conn->req.input.path.len,
   422                                 &minor_version, headers, &num_headers, conn->_prevreqlen);
   423      conn->_prevreqlen = inreqlen;
   424
   425      switch (reqlen) {
   426      default: // parse complete
   427          conn->_reqsize = reqlen;
   428          if ((entity_body_header_index = fixup_request(conn, headers, num_headers, minor_version, &expect)) != -1) {
   429              conn->req.timestamps.request_body_begin_at = *h2o_get_timestamp(conn->super.ctx, NULL, NULL);
   430              if (expect.base != NULL) {
   431                  if (!h2o_lcstris(expect.base, expect.len, H2O_STRLIT("100-continue"))) {
   432                      set_timeout(conn, NULL, NULL);
   433                      h2o_socket_read_stop(conn->sock);
   434                      h2o_send_error_417(&conn->req, "Expectation Failed", "unknown expectation",
   435                                         H2O_SEND_ERROR_HTTP1_CLOSE_CONNECTION);
   436                      return;
   437                  }
   438                  static const h2o_iovec_t res = {H2O_STRLIT("HTTP/1.1 100 Continue\r\n\r\n")};
   439                  h2o_socket_write(conn->sock, (void *)&res, 1, on_continue_sent);
   440              }
   441              if (create_entity_reader(conn, headers + entity_body_header_index) != 0) {
   442                  return;
   443              }
   444              if (expect.base != NULL) {
   445                  /* processing of the incoming entity is postponed until the 100 response is sent */
   446                  h2o_socket_read_stop(conn->sock);
   447                  return;
   448              }
   449              conn->_req_entity_reader->handle_incoming_entity(conn);
   450          } else {
   451              set_timeout(conn, NULL, NULL);
   452              h2o_socket_read_stop(conn->sock);
   453              process_request(conn);
   454          }
   455          return;
   456      case -2: // incomplete
   457          if (inreqlen == H2O_MAX_REQLEN) {
   458              send_bad_request(conn);
   459          }
   460          return;
   461      case -1: // error
   462          /* upgrade to HTTP/2 if the request starts with: PRI * HTTP/2 */
   463          if (conn->super.ctx->globalconf->http1.upgrade_to_http2) {
   464              /* should check up to the first octet that phr_parse_request returns an error */
   465              static const h2o_iovec_t HTTP2_SIG = {H2O_STRLIT("PRI * HTTP/2")};
   466              if (conn->sock->input->size >= HTTP2_SIG.len && memcmp(conn->sock->input->bytes, HTTP2_SIG.base, HTTP2_SIG.len) == 0) {
   467                  h2o_accept_ctx_t accept_ctx = {conn->super.ctx, conn->super.hosts};
   468                  h2o_socket_t *sock = conn->sock;
   469                  struct timeval connected_at = conn->super.connected_at;
   470                  /* destruct the connection after detatching the socket */
   471                  conn->sock = NULL;
   472                  close_connection(conn, 1);
   473                  /* and accept as http2 connection */
   474                  h2o_http2_accept(&accept_ctx, sock, connected_at);
   475                  return;
   476              }
   477          }
   478          if (inreqlen <= 4 && contains_crlf_only(conn->sock->input->bytes, inreqlen)) {
   479              close_connection(conn, 1);
   480          } else {
   481              send_bad_request(conn);
   482          }
   483          return;
   484      }
   485  }
   486
   487  void reqread_on_read(h2o_socket_t *sock, const char *err)
   488  {
   489      struct st_h2o_http1_conn_t *conn = sock->data;
   490
   491      if (err != NULL) {
   492          close_connection(conn, 1);
   493          return;
   494      }
   495
   496      if (conn->_req_entity_reader == NULL)
   497          handle_incoming_request(conn);
   498      else
   499          conn->_req_entity_reader->handle_incoming_entity(conn);
   500  }

500  }
   501
   502  static void reqread_on_timeout(h2o_timeout_entry_t *entry)
   503  {
   504      struct st_h2o_http1_conn_t *conn = H2O_STRUCT_FROM_MEMBER(struct st_h2o_http1_conn_t, _timeout_entry, entry);
   505
   506      if (conn->_req_index == 1) {
   507          /* assign hostconf and bind conf so that the request can be logged */
   508          h2o_hostconf_t *hostconf = h2o_req_setup(&conn->req);
   509          h2o_req_bind_conf(&conn->req, hostconf, &hostconf->fallback_path);
   510          /* set error status for logging */
   511          conn->req.res.reason = "Request Timeout";
   512      }
   513
   514      conn->req.http1_is_persistent = 0;
   515      close_connection(conn, 1);
   516  }
   517
   518  static inline void reqread_start(struct st_h2o_http1_conn_t *conn)
   519  {
   520      set_timeout(conn, &conn->super.ctx->http1.req_timeout, reqread_on_timeout);
   521      h2o_socket_read_start(conn->sock, reqread_on_read);
   522      if (conn->sock->input->size != 0)
   523          handle_incoming_request(conn);
   524  }
   525
   526  static void on_send_next_push(h2o_socket_t *sock, const char *err)
   527  {
   528      struct st_h2o_http1_conn_t *conn = sock->data;
   529
   530      if (err != NULL)
   531          close_connection(conn, 1);
   532      else
   533          h2o_proceed_response(&conn->req);
   534  }
   535
   536  static void on_send_next_pull(h2o_socket_t *sock, const char *err)
   537  {
   538      struct st_h2o_http1_conn_t *conn = sock->data;
   539
   540      if (err != NULL)
   541          close_connection(conn, 1);
   542      else
   543          proceed_pull(conn, 0);
   544  }
   545
   546  static void on_send_complete(h2o_socket_t *sock, const char *err)
   547  {
   548      struct st_h2o_http1_conn_t *conn = sock->data;
   549
   550      assert(conn->req._ostr_top == &conn->_ostr_final.super);
   551
   552      conn->req.timestamps.response_end_at = *h2o_get_timestamp(conn->super.ctx, NULL, NULL);
   553
   554      if (!conn->req.http1_is_persistent) {
   555          /* TODO use lingering close */
   556          close_connection(conn, 1);
   557          return;
   558      }
   559
   560      /* handle next request */
   561      init_request(conn);
   562      h2o_buffer_consume(&conn->sock->input, conn->_reqsize);
   563      conn->_prevreqlen = 0;
   564      conn->_reqsize = 0;
   565      reqread_start(conn);
   566  }
   567
   568  static void on_upgrade_complete(h2o_socket_t *socket, const char *err)
   569  {
   570      struct st_h2o_http1_conn_t *conn = socket->data;
   571      h2o_http1_upgrade_cb cb = conn->upgrade.cb;
   572      void *data = conn->upgrade.data;
   573      h2o_socket_t *sock = NULL;
   574      size_t reqsize = 0;
   575
   576      /* destruct the connection (after detaching the socket) */
   577      if (err == 0) {
   578          sock = conn->sock;
   579          reqsize = conn->_reqsize;
   580          close_connection(conn, 0);
   581      } else {
   582          close_connection(conn, 1);
   583      }
   584
   585      cb(data, sock, reqsize);
   586  }
   587
   588  static size_t flatten_headers_estimate_size(h2o_req_t *req, size_t server_name_and_connection_len)
   589  {
   590      size_t len = sizeof("HTTP/1.1  \r\ndate: \r\nserver: \r\nconnection: \r\ncontent-length: \r\n\r\n") + 3 +
   591                   strlen(req->res.reason) + H2O_TIMESTR_RFC1123_LEN + server_name_and_connection_len +
   592                   sizeof(H2O_UINT64_LONGEST_STR) - 1 + sizeof("cache-control: private") - 1;
   593      const h2o_header_t *header, *end;
   594
   595      for (header = req->res.headers.entries, end = header + req->res.headers.size; header != end; ++header)
   596          len += header->name->len + header->value.len + 4;
   597
   598      return len;
   599  }
